import { Search, User, LogOut, Check, Store } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { SidebarTrigger } from '@/shared/ui/sidebar';
import { ThemeToggle } from '@/shared/ui/ThemeToggle';
import { useAuth } from '@/shared/hooks/useAuth';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { toast } from 'sonner';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
} from '@/shared/ui/dropdown-menu';
import { Avatar, AvatarFallback } from '@/shared/ui/avatar';
import { StoreSelector } from '@/shared/ui/DashboardStoreSelector';
import { useLocation } from 'react-router-dom';
import { useStore } from '@/shared/contexts/StoreContext';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { NotificationBell } from '@/features/funcionarios';
import { GestaoAlertasBell } from '@/features/gestao';

export function DashboardHeader() {
  const { signOut, user } = useAuth();
  const isMobile = useIsMobile();
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';
  const { stores, selectedStore, setSelectedStore } = useStore();
  const { isAdmin } = usePermissions();

  const handleSignOut = async () => {
    await signOut();
    toast.success('Logout realizado com sucesso!');
  };

  const userName = user?.user_metadata?.nome || 'Usuário';
  const userInitials = userName.slice(0, 2).toUpperCase();

  return (
    <header
      className={`${isMobile ? 'h-16' : 'h-14 sm:h-16'} border-b border-border bg-card px-3 sm:px-4 md:px-6 flex items-center justify-between`}
    >
      <div className="flex items-center gap-2 sm:gap-3 md:gap-4 flex-1 min-w-0">
        {/* SidebarTrigger with larger touch target on mobile */}
        <div className={isMobile ? 'p-1' : ''}>
          <SidebarTrigger className={isMobile ? 'h-12 w-12' : ''} />
        </div>

        {isMobile && (
          <div>
            <StoreSelector />
          </div>
        )}

        {!isMobile && (
          <div className="relative max-w-sm lg:max-w-md xl:max-w-lg">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Buscar produtos, movimentações..."
              className="pl-10 w-full"
            />
          </div>
        )}
      </div>

      <div
        className={`flex items-center ${isMobile ? 'gap-2' : 'gap-1 sm:gap-2 md:gap-4'}`}
      >
        {/* Search button with larger touch target on mobile */}
        {isMobile && (
          <Button
            variant="ghost"
            size="icon"
            className="h-12 w-12 rounded-xl" // Larger touch target and rounded corners for mobile
          >
            <Search className="h-5 w-5" />
          </Button>
        )}

        {isDashboard && (
          <div className="hidden sm:block">
            <ThemeToggle />
          </div>
        )}

        {/* Sinos de notificação: RH (master) + Gestão (gestores) */}
        <NotificationBell />
        <GestaoAlertasBell />

        {/* User dropdown with larger touch target on mobile */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              className={`relative ${isMobile ? 'h-12 w-12' : 'h-8 w-8 sm:h-9 sm:w-9'} rounded-full`}
            >
              <Avatar
                className={isMobile ? 'h-12 w-12' : 'h-8 w-8 sm:h-9 sm:w-9'}
              >
                <AvatarFallback
                  className={`bg-primary text-primary-foreground ${isMobile ? 'text-base' : 'text-xs sm:text-sm'}`}
                >
                  {userInitials}
                </AvatarFallback>
              </Avatar>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            className={`${isMobile ? 'w-64' : 'w-56'}`}
            align="end"
            forceMount
            sideOffset={isMobile ? 8 : 4} // More spacing on mobile
          >
            <DropdownMenuLabel className="font-normal">
              <div className="flex flex-col space-y-1">
                <p
                  className={`${isMobile ? 'text-base' : 'text-sm'} font-medium leading-none`}
                >
                  {userName}
                </p>
                <p
                  className={`${isMobile ? 'text-sm' : 'text-xs'} leading-none text-muted-foreground`}
                >
                  {user?.email}
                </p>
              </div>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            {isMobile && (
              <>
                <DropdownMenuSub>
                  <DropdownMenuSubTrigger className="py-3">
                    Loja:{' '}
                    {selectedStore?.shortName ||
                      selectedStore?.name ||
                      'Selecionar'}
                  </DropdownMenuSubTrigger>
                  <DropdownMenuSubContent className="w-64">
                    {isAdmin() ? (
                      stores.map((store) => (
                        <DropdownMenuItem
                          key={store.id}
                          onClick={() => setSelectedStore(store)}
                          className="flex items-center justify-between cursor-pointer py-2"
                        >
                          <div className="flex items-center gap-2">
                            <Store className="h-4 w-4 text-muted-foreground" />
                            <div className="flex flex-col">
                              <span className="text-sm font-medium">
                                {store.name}
                              </span>
                              {store.address && (
                                <span className="text-xs text-muted-foreground">
                                  {store.address}
                                </span>
                              )}
                            </div>
                          </div>
                          {selectedStore?.id === store.id && (
                            <Check className="h-4 w-4 text-primary" />
                          )}
                        </DropdownMenuItem>
                      ))
                    ) : (
                      <DropdownMenuItem className="py-2" disabled>
                        <span className="flex-1">
                          {selectedStore?.name || 'Loja'}
                        </span>
                      </DropdownMenuItem>
                    )}
                  </DropdownMenuSubContent>
                </DropdownMenuSub>
                <DropdownMenuSeparator />
              </>
            )}

            <DropdownMenuItem className={isMobile ? 'py-3' : ''}>
              {' '}
              {/* Larger touch target on mobile */}
              <User className={`mr-2 ${isMobile ? 'h-5 w-5' : 'h-4 w-4'}`} />
              <span className={isMobile ? 'text-base' : ''}>Perfil</span>
            </DropdownMenuItem>

            {isMobile && isDashboard && (
              <DropdownMenuItem className="py-3">
                {' '}
                {/* Larger touch target */}
                <div className="mr-2 h-5 w-5 flex items-center justify-center">
                  <ThemeToggle />
                </div>
                <span className="text-base">Tema</span>
              </DropdownMenuItem>
            )}

            <DropdownMenuItem
              onClick={handleSignOut}
              className={isMobile ? 'py-3' : ''} // Larger touch target on mobile
            >
              <LogOut className={`mr-2 ${isMobile ? 'h-5 w-5' : 'h-4 w-4'}`} />
              <span className={isMobile ? 'text-base' : ''}>Sair</span>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

