  <SidebarGroupContent>
    <SidebarMenu>
      {renderMenuItems(logisticaItems)}
    </SidebarMenu>
  </SidebarGroupContent>
</SidebarGroup>

{/* Financeiro */}
<SidebarGroup>
  <SidebarGroupLabel>Financeiro</SidebarGroupLabel>
  <SidebarGroupContent>
    <SidebarMenu>
      {renderMenuItems(financeiroItems)}
    </SidebarMenu>
  </SidebarGroupContent>
</SidebarGroup>


{/* DP/RH */}
<SidebarGroup>
  <SidebarGroupLabel>DP/RH</SidebarGroupLabel>
